local HatBandMaker = {}
local PRODUCTS = {
    iron_hat_band = { name = "Železna poroka za klobuke", ironCost = 1, woodCost = 1, leatherCost = 3, time = 5, cost = 140, prestige = 3, happiness = 2, description = "Železna poroka za klobuke." },
    bronze_hat_band = { name = "Bronasta poroka za klobuke", bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 3, time = 7, cost = 340, prestige = 5, happiness = 3, description = "Bronasta poroka za klobučarje." },
    silver_hat_band = { name = "Srebrna poroka za klobuke", silverCost = 1, bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 3, time = 11, cost = 820, prestige = 10, happiness = 4, description = "Srebrna poroka za plemiške klobučarje." },
    gilded_hat_band = { name = "Pozlačena poroka za klobuke", goldCost = 1, silverCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 3, time = 15, cost = 1780, prestige = 19, happiness = 5, description = "Pozlačena poroka za dvorne klobučarje." },
    jewel_set_hat_band = { name = "Draguljasta poroka za klobuke", goldCost = 2, silverCost = 1, jewelCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 3, time = 19, cost = 3850, prestige = 35, happiness = 7, description = "Draguljasta poroka za kraljeve klobučarje." },
    royal_sovereign_hat_band = { name = "Kraljevski suverena poroka za klobuke", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 4, time = 26, cost = 8300, prestige = 67, happiness = 13, description = "Suverena poroka z biseri za krono." },
}
local BUILDINGS = {
    hatband_workshop = { name = "Poročna delavnica", cost = { gold = 300, wood = 180, stone = 125, iron = 6 }, upkeep = 5, qualityBonus = 5 },
    hatband_house = { name = "Poročna hiša", cost = { gold = 1110, wood = 360, stone = 255, silver = 6, iron = 6 }, upkeep = 23, qualityBonus = 18 },
    master_hatband_atelier = { name = "Mojstrski poročni atelje", cost = { gold = 2850, wood = 420, stone = 495, silver = 32, gold = 6 }, upkeep = 67, qualityBonus = 30 },
    sovereign_hatband_palace = { name = "Suverena poročna palača", cost = { gold = 12400, wood = 650, stone = 800, gold = 79, jewel = 18 }, upkeep = 245, qualityBonus = 55, prestigeBonus = 50 },
}
HatBandMaker.ironStock = 10; HatBandMaker.bronzeStock = 8; HatBandMaker.woodStock = 12; HatBandMaker.leatherStock = 16; HatBandMaker.silverStock = 8; HatBandMaker.goldStock = 6; HatBandMaker.jewelStock = 4; HatBandMaker.pearlStock = 4
HatBandMaker.productStock = {}; HatBandMaker.buildings = {}; HatBandMaker.maker = nil; HatBandMaker.activeMaking = {}; HatBandMaker.totalProducts = 0; HatBandMaker.dayTimer = 0
function HatBandMaker.init() HatBandMaker.ironStock=10; HatBandMaker.bronzeStock=8; HatBandMaker.woodStock=12; HatBandMaker.leatherStock=16; HatBandMaker.silverStock=8; HatBandMaker.goldStock=6; HatBandMaker.jewelStock=4; HatBandMaker.pearlStock=4; HatBandMaker.productStock={}; HatBandMaker.buildings={}; HatBandMaker.maker=nil; HatBandMaker.activeMaking={}; HatBandMaker.totalProducts=0; HatBandMaker.dayTimer=0; print("[HatBandMaker] Royal Hat Band Maker System initialized (6 products, 4 buildings)") end
function HatBandMaker.hireMaker(n,s) s=s or math.random(55,90); local c=570+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; HatBandMaker.maker={name=n or ("Poročnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Poročnik najet: %s (spretnost: %d)",HatBandMaker.maker.name,s),"success") end; return true end
function HatBandMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function HatBandMaker.build(id) local ok,e=HatBandMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(HatBandMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function HatBandMaker.getQualityBonus() local b=0; for _,bd in ipairs(HatBandMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function HatBandMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and HatBandMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and HatBandMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and HatBandMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and HatBandMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and HatBandMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and HatBandMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and HatBandMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and HatBandMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #HatBandMaker.buildings==0 then return false,"Potrebna poročna delavnica" end; if not HatBandMaker.maker then return false,"Potreben poročnik" end; return true end
function HatBandMaker.make(pt,qty) qty=qty or 1; local ok,e=HatBandMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then HatBandMaker.ironStock=HatBandMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then HatBandMaker.bronzeStock=HatBandMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then HatBandMaker.woodStock=HatBandMaker.woodStock-d.woodCost*qty end; if d.leatherCost then HatBandMaker.leatherStock=HatBandMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then HatBandMaker.silverStock=HatBandMaker.silverStock-d.silverCost*qty end; if d.goldCost then HatBandMaker.goldStock=HatBandMaker.goldStock-d.goldCost*qty end; if d.jewelCost then HatBandMaker.jewelStock=HatBandMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then HatBandMaker.pearlStock=HatBandMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if HatBandMaker.maker then t=math.max(1,t-math.floor(HatBandMaker.maker.skill/13)) end; table.insert(HatBandMaker.activeMaking,{id="hatband_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function HatBandMaker.completeMaking(m) local q=1.0+(HatBandMaker.getQualityBonus()/100); if HatBandMaker.maker then q=q+(HatBandMaker.maker.skill/140) end; q=math.min(2.5,q); HatBandMaker.productStock[m.productType]=(HatBandMaker.productStock[m.productType] or 0)+m.quantity; HatBandMaker.totalProducts=HatBandMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if HatBandMaker.maker then HatBandMaker.maker.itemsMade=HatBandMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then HatBandMaker.maker.skill=math.min(100,HatBandMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Poroka izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"hatband.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function HatBandMaker.update(dt) if not _G.state then return end; HatBandMaker.dayTimer=HatBandMaker.dayTimer+dt; if HatBandMaker.dayTimer>=30 then HatBandMaker.dayTimer=0; for i=#HatBandMaker.activeMaking,1,-1 do local m=HatBandMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HatBandMaker.completeMaking(m); table.remove(HatBandMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HatBandMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HatBandMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function HatBandMaker.getStats() return {ironStock=HatBandMaker.ironStock,bronzeStock=HatBandMaker.bronzeStock,woodStock=HatBandMaker.woodStock,leatherStock=HatBandMaker.leatherStock,silverStock=HatBandMaker.silverStock,goldStock=HatBandMaker.goldStock,jewelStock=HatBandMaker.jewelStock,pearlStock=HatBandMaker.pearlStock,productStock=HatBandMaker.productStock,numBuildings=#HatBandMaker.buildings,hasMaker=HatBandMaker.maker~=nil,makerName=HatBandMaker.maker and HatBandMaker.maker.name or "—",makerSkill=HatBandMaker.maker and HatBandMaker.maker.skill or 0,activeMaking=#HatBandMaker.activeMaking,totalProducts=HatBandMaker.totalProducts} end
return HatBandMaker
